"""The ground truth: twenty hand-built records and the expansion they must produce.

`CONVENTIONS.md` §14 makes this directory the only place LAW-DOMAIN vocabulary may appear in
tests. This module is the fixture modules 3 and 4 are held to, and it is meant to be kept
forever: it is the one artifact in the repository that states what the row-to-event
transformation should do, independently of what it does.

How the expectations were derived, and why that matters
-------------------------------------------------------
`EXPECTED_ORDER_EVENTS` and `EXPECTED_LINE_EVENTS` were written by reading each event type's
`derivation.basis` PROSE in `ontology/packs/dataco/ontology.yaml` against each row's status
columns, by hand, one order at a time. They were NOT generated by running the code and
recording what came out -- an expectation produced that way asserts only that the code is
what it is, and it agrees with any bug that was present when it was written.

They are literal sets, not predicates. A predicate here would be a second implementation of
the emission rules, and two implementations of the same idea agree with each other's
mistakes.

The twenty rows cover, deliberately:
  * an order with two lines, so occurrence deduplication has something to deduplicate;
  * every declared process variant -- happy path, review, held, fraud, cancellation before
    dispatch, stock shortfall, late delivery;
  * a shipped order still sitting at `PENDING`, which the pack's state machine does not
    admit and the real dataset contains;
  * a realised shipping duration of zero, which is the boundary of `SHIPMENT_IN_TRANSIT`;
  * one attribute disagreement between two records about one participant, so identity
    reconciliation has one conflict to reconcile and exactly one.
"""

from __future__ import annotations

from typing import Final

__all__ = [
    "EXPECTED_ATTRIBUTE_CONFLICTS",
    "EXPECTED_ENTITY_COUNTS",
    "EXPECTED_EVENT_COUNTS",
    "EXPECTED_EVENT_TOTAL",
    "EXPECTED_LINE_EVENTS",
    "EXPECTED_NEVER_EMITTED",
    "EXPECTED_ORDER_EVENTS",
    "GROUND_TRUTH_DATASET_VERSION",
    "ORDERS",
    "OrderCase",
    "rows",
]

#: A fixed, synthetic `dataset_version`. The fixture must not move when the real file or the
#: real mapping is re-pinned: this is ground truth about the TRANSFORMATION, not about the
#: published distribution.
GROUND_TRUTH_DATASET_VERSION: Final[str] = "groundtruth@0000000000000000+map0000000000000000"


class OrderCase:
    """One order in the fixture: its status columns and how many lines it carries."""

    def __init__(
        self,
        reference: int,
        order_status: str,
        delivery_status: str,
        scheduled_days: int,
        real_days: int,
        lines: int,
    ) -> None:
        """Record one order's declared shape."""
        self.reference = reference
        self.order_status = order_status
        self.delivery_status = delivery_status
        self.scheduled_days = scheduled_days
        self.real_days = real_days
        self.lines = lines


