#: Exactly one record disagrees with another about one attribute of one participant: the two
#: lines of order 2 name customer 502 and give it two different states.
EXPECTED_ATTRIBUTE_CONFLICTS: Final[int] = 1


def rows() -> tuple[dict[str, str], ...]:
    """Return the twenty raw records, in canonical row sequence.

    Raw, exactly as a delimited source would present them: every value is text and nothing
    has been transformed. The transforms are the mapping's business and are applied by
    `schema_mapper.clean_values`, so the fixture exercises that path rather than assuming it.
    """
    built: list[dict[str, str]] = []
    line_reference = 100
    for case in ORDERS:
        placed_day = case.reference
        for line in range(case.lines):
            line_reference += 1
            built.append(
                {
                    "Order Id": str(case.reference),
                    "Order Status": case.order_status,
                    "Type": "DEBIT",
                    # Every line of one order carries ONE order instant, as the real source
                    # does. Varying it per line would make each line a separate occurrence
                    # and would quietly defeat the deduplication this fixture exists to
                    # check -- which is how the first draft of this fixture was wrong.
                    "order date (DateOrders)": f"1/{placed_day}/2018 09:00",
                    "shipping date (DateOrders)": (
                        f"1/{placed_day + case.scheduled_days}/2018 09:00"
                    ),
                    "Days for shipment (scheduled)": str(case.scheduled_days),
                    "Days for shipping (real)": str(case.real_days),
                    "Delivery Status": case.delivery_status,
                    "Late_delivery_risk": "1" if case.real_days > case.scheduled_days else "0",
                    "Order Profit Per Order": "91.25",
                    "Benefit per order": "91.25",
                    "Order Item Id": str(line_reference),
                    "Order Item Quantity": "1",
                    "Order Item Product Price": "327.75",
                    "Order Item Discount": "13.11",
                    "Order Item Discount Rate": "0.04",
                    "Order Item Total": "314.64",
                    "Order Item Profit Ratio": "0.29",
                    "Customer Id": str(500 + case.reference),
                    "Customer Segment": "Consumer",
                    "Customer City": "Caguas",
                    # The one planted disagreement: order 2's second line names a different
                    # state for the same customer. One conflict, in one attribute, of one
                    # participant -- enough to exercise every ConflictPolicy and few enough
                    # that the count is checkable by eye.
                    "Customer State": ("NY" if case.reference == 2 and line == 1 else "PR"),
                    "Customer Country": "Puerto Rico",
                    "Customer Zipcode": "725",
                    "Product Card Id": str(700 + (line_reference % 3)),
                    "Product Name": "Instrument",
                    "Product Price": "327.75",
                    "Product Status": "0",
                    "Category Id": "73",
                    "Category Name": "Recreation",
                    "Department Id": "2",
                    "Department Name": "Leisure",
                    "Latitude": "18.25",
                    "Longitude": "-66.03",
                    "Market": "Pacific Asia",
                    "Order Region": "Southeast Asia",
                    "Order Country": "Indonesia",
                    "Order State": "Java Occidental",
                    "Order City": "Bekasi",
                    "Shipping Mode": "Standard Class",
                }
            )
    return tuple(built)
